def transform(grid):
    """Fill one-cell background gaps between repeated foreground marks in rows."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if not row:
            continue
        background = max(set(row), key=row.count)
        marks = {v for v in row if v != background}
        if len(marks) != 1:
            continue
        mark = next(iter(marks))
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == mark and row[c + 1] == mark:
                out[r][c] = 2
    return out
